# Purpose: track original A-H objects through documented split/fuse edges.
# Run via source() from the report after workflow 03 defines the project root.
# Input: outplant_interval_rows in memory, generated by workflow 03.
# Outputs: per-object tracking and cohort summaries in outputs/Tables/.
# Assumptions: an original object is one annotated individual, not necessarily
# one planted fragment. A living descendant indicates lineage continuity, not
# proof that every contributor's tissue persists after fusion. No inferred edges.

# Settings ----
lineage_baselines <- as.Date(c("2025-05-07", "2026-04-09"))
lineage_cohort_names <- c("2025 original outplants", "April 2026 additions")

# File paths ----
lineage_project_root <- outplant_find_project_root()
lineage_input <- file.path(lineage_project_root, "data_processed", "outplant_interval_rows.csv")
lineage_output_dir <- file.path(lineage_project_root, "outputs", "Tables")

# 1. Read actual object correspondences ----
lineage_rows <- outplant_interval_rows |>
  dplyr::mutate(blob_start = as.character(blob_start), blob_end = as.character(blob_end))
lineage_results <- list()
lineage_result_index <- 0L

# 2. Define baseline objects, then follow directed edges one interval at a time ----
for (lineage_plot in sort(unique(lineage_rows$plot))) {
 for (lineage_section in sort(unique(lineage_rows$plot_section[lineage_rows$plot == lineage_plot]))) {
  section_rows <- lineage_rows |> dplyr::filter(plot == lineage_plot, plot_section == lineage_section)
  positive_dates <- c(section_rows$month_start_date[section_rows$present_start],
                      section_rows$month_end_date[section_rows$present_end])
  if (length(positive_dates) == 0L) next
  lineage_baselines <- if (lineage_plot == "Plot E") as.Date(c("2025-05-07", "2026-04-09")) else min(positive_dates)
  lineage_cohort_names <- if (lineage_plot == "Plot E") c("2025 original outplants", "April 2026 additions") else "Initial observed cohort"
  for (cohort_index in seq_along(lineage_baselines)) {
    baseline_date <- lineage_baselines[cohort_index]
    if (cohort_index == 1L && any(section_rows$month_start_date == baseline_date)) {
      roots <- section_rows |>
        dplyr::filter(month_start_date == baseline_date, present_start) |>
        dplyr::pull(blob_start) |> unique()
    } else {
      april_rows <- section_rows |> dplyr::filter(month_end_date == baseline_date)
      # New April objects have positive destination area but no living source
      # connected to that destination. This is first appearance, not deployment proof.
      incoming <- april_rows |>
        dplyr::filter(present_start, present_end) |> dplyr::pull(blob_end)
      roots <- april_rows |>
        dplyr::filter(present_end, cohort_index == 1L | !blob_end %in% incoming) |>
        dplyr::pull(blob_end) |> unique()
    }
    stopifnot(!anyNA(roots), !any(roots == "-1"))
    interval_dates <- sort(unique(section_rows$month_end_date[
      section_rows$month_start_date >= baseline_date]))
    interval_index <- lapply(split(section_rows, as.character(section_rows$month_end_date)),
      function(interval_rows) split(interval_rows[interval_rows$present_start, ],
                                    interval_rows$blob_start[interval_rows$present_start]))
    for (root_object in roots) {
      descendants <- root_object
      unresolved_branch <- FALSE
      previous_date <- baseline_date
      for (step_index in seq_len(length(interval_dates) + 1L)) {
        if (step_index == 1L) {
          survey_date <- baseline_date
        } else {
          survey_date <- interval_dates[step_index - 1L]
          current_sources <- interval_index[[as.character(survey_date)]]
          next_descendants <- character()
          for (object_id in descendants) {
            connections <- current_sources[[object_id]]
            if (is.null(connections)) connections <- section_rows[0, ]
            connections <- connections[connections$month_start_date == previous_date, ]
            live_connections <- connections[connections$present_end, ]
            if (nrow(live_connections) > 0L) {
              next_descendants <- union(next_descendants, live_connections$blob_end)
            } else if (nrow(connections) == 0L ||
                       !all(!is.na(connections$action) & connections$action == "dead")) {
              # Missing correspondence is unknown, never an inferred death.
              unresolved_branch <- TRUE
            }
          }
          descendants <- unique(next_descendants)
        }
        status <- if (length(descendants) > 0L) {
          "Living descendant observed"
        } else if (unresolved_branch) {
          "Unresolved tracking gap"
        } else {
          "All tracked descendants recorded dead"
        }
        lineage_result_index <- lineage_result_index + 1L
        lineage_results[[lineage_result_index]] <- tibble::tibble(
          plot = lineage_plot, plot_section = lineage_section,
          cohort = lineage_cohort_names[cohort_index], first_present = baseline_date,
          original_object_id = root_object,
          original_individual_id = paste(lineage_section, baseline_date, root_object, sep = "__"),
          survey_date = survey_date, tracking_status = status,
          n_living_descendants = length(descendants),
          living_descendant_ids = paste(sort(descendants), collapse = ";"),
          has_unresolved_branch = unresolved_branch
        )
        previous_date <- survey_date
      }
    }
  }
}
}
outplant_object_lineage_tracking <- dplyr::bind_rows(lineage_results)

# 3. Summarize original individuals once, irrespective of descendant count ----
outplant_object_lineage_survival <- outplant_object_lineage_tracking |>
  dplyr::group_by(plot, cohort, first_present, survey_date) |>
  dplyr::summarise(
    n_baseline = dplyr::n_distinct(original_individual_id),
    n_surviving = sum(n_living_descendants > 0L),
    n_recorded_dead = sum(tracking_status == "All tracked descendants recorded dead"),
    n_unresolved = sum(tracking_status == "Unresolved tracking gap"),
    .groups = "drop") |>
  dplyr::mutate(percent_survival = 100 * n_surviving / n_baseline,
                percent_unresolved = 100 * n_unresolved / n_baseline)
stopifnot(all(with(outplant_object_lineage_survival,
                   n_baseline == n_surviving + n_recorded_dead + n_unresolved)))

# 4. Preserve the established E audit schema ----
plot_e_object_lineage_tracking <- outplant_object_lineage_tracking |> dplyr::filter(plot == "Plot E")
plot_e_object_lineage_survival <- outplant_object_lineage_survival |> dplyr::filter(plot == "Plot E") |> dplyr::select(-plot)
for (table_name in c("outplant_object_lineage_tracking", "outplant_object_lineage_survival",
                     "plot_e_object_lineage_tracking", "plot_e_object_lineage_survival")) {
  readr::write_csv(get(table_name), file.path(lineage_output_dir, paste0(table_name, ".csv")))
}

# 5. Cumulative summaries retain existing download columns, with explicit unknowns ----
# Each plot's initial observed cohort is separate from later additions. Confidence
# limits are unavailable because fused originals share descendants and are dependent.
outplant_section_cumulative_survival_summary <- outplant_object_lineage_tracking |>
  filter(plot != "Plot E" | cohort == "2025 original outplants") |>
  group_by(plot, plot_section, first_present, survey_date) |>
  summarise(n_baseline = n(), n_surviving_from_baseline = sum(n_living_descendants > 0),
            cumulative_deaths_observed = sum(tracking_status == "All tracked descendants recorded dead"),
            n_unresolved = sum(tracking_status == "Unresolved tracking gap"), .groups = "drop") |>
  group_by(plot, plot_section) |> arrange(survey_date, .by_group = TRUE) |>
  mutate(plot_section_label = paste(plot, plot_section), month_order = row_number(),
         month = format(survey_date, "%B"), baseline_date = first_present,
         baseline_month = format(first_present, "%B"),
         n_died_interval = cumulative_deaths_observed - lag(cumulative_deaths_observed, default = 0L),
         percent_cumulative_survival = 100 * n_surviving_from_baseline / n_baseline,
         percent_cumulative_survival_low = NA_real_, percent_cumulative_survival_high = NA_real_,
         baseline_surviving_area_m2 = NA_real_, method = "Original-object lineage persistence") |> ungroup()
lineage_expected_sections <- lineage_rows |> distinct(plot, plot_section) |> count(plot, name = "expected_plot_sections")
outplant_cumulative_survival_summary <- outplant_section_cumulative_survival_summary |>
  group_by(plot, survey_date) |>
  summarise(n_plot_sections = n_distinct(plot_section),
            plot_section_labels = paste(sort(unique(plot_section_label)), collapse = "; "),
            baseline_date = min(baseline_date),
            across(c(n_baseline, n_died_interval, cumulative_deaths_observed,
                     n_surviving_from_baseline, n_unresolved), sum), .groups = "drop") |>
  left_join(lineage_expected_sections, by = "plot") |>
  filter(n_plot_sections == expected_plot_sections) |>
  group_by(plot) |> arrange(survey_date, .by_group = TRUE) |>
  mutate(plot_section = "all", plot_section_label = plot,
         month_order = row_number(), month = format(survey_date, "%B"),
         baseline_month = format(baseline_date, "%B"),
         percent_cumulative_survival = 100 * n_surviving_from_baseline / n_baseline,
         percent_cumulative_survival_low = NA_real_, percent_cumulative_survival_high = NA_real_,
         baseline_surviving_area_m2 = NA_real_, method = "Original-object lineage persistence") |> ungroup()
stopifnot(all(with(outplant_cumulative_survival_summary,
  n_baseline == n_surviving_from_baseline + cumulative_deaths_observed + n_unresolved)))

# 6. Adjacent intervals count unique source objects rather than Genet groups ----
lineage_interval_results <- list()
lineage_birth_results <- list()
interval_groups <- c("plot", "plot_section", "plot_section_label", "interval_order",
                     "month_start", "month_end", "month_start_date", "month_end_date")
for (rr in split(lineage_rows, interaction(lineage_rows$plot, lineage_rows$plot_section,
                                          lineage_rows$interval_order, drop = TRUE))) {
  interval <- rr[1, interval_groups]
  sources <- unique(rr$blob_start[rr$present_start])
  incoming <- unique(rr$blob_end[rr$present_start & rr$present_end])
  births <- setdiff(unique(rr$blob_end[rr$present_end]), incoming)
  lineage_birth_results[[length(lineage_birth_results) + 1L]] <- interval |> mutate(n_born = length(births))
  for (object_id in sources) {
    edges <- rr[rr$present_start & rr$blob_start == object_id, ]
    species_values <- unique(edges$species)
    stopifnot(length(species_values) == 1L)
    live <- unique(edges$blob_end[edges$present_end])
    status <- if (length(live) > 0L) "Living descendant observed" else if (
      all(!is.na(edges$action) & edges$action == "dead")) "All tracked descendants recorded dead" else "Unresolved tracking gap"
    lineage_interval_results[[length(lineage_interval_results) + 1L]] <- interval |>
      mutate(source_object_id = object_id, species = species_values, tracking_status = status,
             living_descendant_ids = paste(sort(live), collapse = ";"))
  }
}
outplant_object_interval_tracking <- bind_rows(lineage_interval_results)
lineage_births <- bind_rows(lineage_birth_results)
outplant_section_species_survival_summary <- outplant_object_interval_tracking |>
  group_by(across(all_of(c(interval_groups, "species")))) |>
  summarise(n_start = n(), n_survived = sum(tracking_status == "Living descendant observed"),
            n_died = sum(tracking_status == "All tracked descendants recorded dead"),
            n_unresolved = sum(tracking_status == "Unresolved tracking gap"), .groups = "drop")
outplant_section_survival_summary <- outplant_section_species_survival_summary |>
  group_by(across(all_of(interval_groups))) |>
  summarise(across(c(n_start, n_survived, n_died, n_unresolved), sum), .groups = "drop") |>
  full_join(lineage_births, by = interval_groups) |>
  mutate(across(c(n_start, n_survived, n_died, n_unresolved), ~ replace_na(.x, 0L)))
plot_groups <- setdiff(interval_groups, c("plot_section", "plot_section_label"))
outplant_survival_summary <- outplant_section_survival_summary |>
  group_by(across(all_of(plot_groups))) |>
  summarise(across(c(n_start, n_survived, n_died, n_unresolved, n_born), sum), .groups = "drop") |>
  mutate(plot_section = "all", plot_section_label = plot)
outplant_species_survival_summary <- outplant_section_species_survival_summary |>
  group_by(across(all_of(c(plot_groups, "species")))) |>
  summarise(across(c(n_start, n_survived, n_died, n_unresolved), sum), .groups = "drop") |>
  mutate(plot_section = "all", plot_section_label = plot)
for (table_name in c("outplant_section_survival_summary", "outplant_survival_summary",
                     "outplant_section_species_survival_summary", "outplant_species_survival_summary")) {
  interval_summary <- get(table_name) |>
    mutate(percent_survival = if_else(n_start > 0L, 100 * n_survived / n_start, NA_real_),
           percent_survival_low = NA_real_, percent_survival_high = NA_real_,
           interval_label = paste(format(month_start_date, "%d %b %Y"), "to", format(month_end_date, "%d %b %Y")),
           method = "Source-object descendant retention")
  stopifnot(all(with(interval_summary, n_start == n_survived + n_died + n_unresolved)))
  assign(table_name, interval_summary)
}
readr::write_csv(outplant_object_interval_tracking,
                 file.path(lineage_output_dir, "outplant_object_interval_tracking.csv"))
